package com.streamcraft.core.runtime;
import com.streamcraft.shared.file.HdfsFileSourceConfig; import java.io.IOException; import java.util.*; import java.util.regex.Pattern; import org.apache.flink.api.connector.source.*; import org.apache.flink.core.fs.*;
final class HdfsFileEnumerator implements SplitEnumerator<HdfsFileSourceSplit,HdfsFileEnumeratorState>{private final SplitEnumeratorContext<HdfsFileSourceSplit> context;private final HdfsFileSourceConfig config;private final Map<String,HdfsFileSourceSplit> pending=new LinkedHashMap<>();private final Set<String>known=new TreeSet<>();private final Set<Integer>waiting=new TreeSet<>();private final Set<Integer>noMoreSignaled=new HashSet<>();private final Pattern filter;private boolean boundedDiscoveryComplete;
 HdfsFileEnumerator(SplitEnumeratorContext<HdfsFileSourceSplit> c,HdfsFileSourceConfig cfg,HdfsFileEnumeratorState s)throws Exception{context=c;config=cfg;filter=cfg.fileFilterPattern().isBlank()?null:Pattern.compile(cfg.fileFilterPattern());known.addAll(s.knownSplitIds());s.pendingSplits().forEach(x->pending.put(x.splitId(),x));}
 public void start(){if(config.readMode()==HdfsFileSourceConfig.ReadMode.INCREMENTAL){context.callAsync(this::discoverFiles,this::handleDiscovery,0L,config.pollIntervalMillis());}else{try{boundedDiscoveryComplete=true;handleDiscovery(discoverFiles(),null);}catch(Exception e){throw new IllegalStateException("HDFS File Source discovery failed: "+e.getMessage(),e);}}} public void handleSplitRequest(int id,String h){waiting.add(id);assign();}public void addReader(int id){noMoreSignaled.remove(id);waiting.add(id);assign();}public void addSplitsBack(List<HdfsFileSourceSplit>s,int id){s.forEach(x->pending.put(x.splitId(),x));waiting.add(id);assign();}public HdfsFileEnumeratorState snapshotState(long id){return new HdfsFileEnumeratorState(new ArrayList<>(pending.values()),known);}public void close()throws IOException{}
 private List<HdfsFileSourceSplit> discoverFiles() throws Exception{Path root=HdfsFileRuntimeSupport.resolvePath(config.defaultFs(),config.path());List<Path>files=new ArrayList<>();collect(root,files);List<HdfsFileSourceSplit> discovered=new ArrayList<>();for(Path p:files){FileStatus st=p.getFileSystem().getFileStatus(p);if(config.readMode()==HdfsFileSourceConfig.ReadMode.INCREMENTAL&&System.currentTimeMillis()-st.getModificationTime()<config.pollIntervalMillis())continue;String fp=p.toString()+":"+st.getLen()+":"+st.getModificationTime();if(known.add(fp))discovered.add(new HdfsFileSourceSplit(fp,new HdfsFileSourceState(p.toString(),fp,0,0,config.fileFormatType().name(),false,false)));}return discovered;}
 private void handleDiscovery(List<HdfsFileSourceSplit> discovered,Throwable error){if(error!=null)throw new IllegalStateException("HDFS File Source discovery failed: "+error.getMessage(),error);if(discovered!=null)for(HdfsFileSourceSplit s:discovered)pending.put(s.splitId(),s);assign();}
 private void collect(Path p,List<Path> out)throws Exception{FileSystem fs=p.getFileSystem();FileStatus s=fs.getFileStatus(p);if(!s.isDir()){if(filter==null||filter.matcher(p.toString()).matches()||filter.matcher(p.getName()).matches())out.add(p);return;}FileStatus[]cs=fs.listStatus(p);if(cs!=null)for(FileStatus c:cs)collect(c.getPath(),out);}
 private void assign(){if(pending.isEmpty()){signalBoundedReaders();return;}Map<Integer,?>readers=context.registeredReaders();List<Integer> targets=waiting.stream().filter(readers::containsKey).toList();if(targets.isEmpty())targets=readers.keySet().stream().sorted().toList();if(targets.isEmpty())return;Map<Integer,List<HdfsFileSourceSplit>>a=new LinkedHashMap<>();int i=0;for(HdfsFileSourceSplit s:new ArrayList<>(pending.values())){int id=targets.get(i++%targets.size());a.computeIfAbsent(id,k->new ArrayList<>()).add(s);pending.remove(s.splitId());}context.assignSplits(new SplitsAssignment<>(a));waiting.removeAll(a.keySet());signalBoundedReaders();}
 private void signalBoundedReaders(){if(!boundedDiscoveryComplete||!pending.isEmpty())return;context.registeredReaders().keySet().stream().sorted().filter(noMoreSignaled::add).forEach(context::signalNoMoreSplits);}
}
